html:
{{ oc_reissue_mark(doc) }}
{%- set r = oc_graduate_record(doc, "Consolidated Grade Sheet") -%}
{% if r.draft_preview %}<div style="border:3px solid #c0392b;color:#c0392b;font-size:28px;font-weight:bold;text-align:center;padding:8px;margin-bottom:12px;letter-spacing:4px">{{ _("DRAFT - NOT VALID") }}</div>{% endif %}
<h3 style="text-align:center">{{ _("Consolidated Grade Sheet") }}</h3>
<p style="text-align:center">{{ doc.company|e }}</p>
<table class="table table-bordered table-condensed">
  <tr><th>{{ _("Student") }}</th><td>{{ r.student_name|e }} ({{ (r.register_no or r.student)|e }})</td>
      <th>{{ _("Programme") }}</th><td>{{ r.program|e }}</td></tr>
  <tr><th>{{ _("Regulation") }}</th><td>{{ r.regulation|e }}</td>
      <th>{{ _("Certificate No.") }}</th><td>{{ (doc.certificate_number or "")|e }}</td></tr>
</table>
<table class="table table-bordered table-condensed">
  <thead><tr><th>{{ _("Course") }}</th><th>{{ _("Title") }}</th><th class="text-right">{{ _("Credits") }}</th>
    <th>{{ _("Grade") }}</th><th class="text-right">{{ _("GP") }}</th></tr></thead>
  <tbody>
  {% for row in r.core_courses %}
    <tr><td>{{ row.course|e }}</td><td>{{ (row.course_name or "")|e }}</td><td class="text-right">{{ row.credits }}</td>
      <td>{{ (row.grade or "")|e }}</td><td class="text-right">{{ row.grade_point }}</td></tr>
  {% endfor %}
  </tbody>
</table>
{% if r.additional_courses %}
<h5>{{ _("Additional, Honours and Minor courses") }}</h5>
<table class="table table-bordered table-condensed">
  <thead><tr><th>{{ _("Course") }}</th><th>{{ _("Title") }}</th><th class="text-right">{{ _("Credits") }}</th>
    <th>{{ _("Grade") }}</th><th class="text-right">{{ _("GP") }}</th><th>{{ _("Type") }}</th><th>{{ _("CGPA") }}</th></tr></thead>
  <tbody>
  {% for row in r.additional_courses %}
    <tr><td>{{ row.course|e }}</td><td>{{ (row.course_name or "")|e }}</td><td class="text-right">{{ row.credits }}</td>
      <td>{{ (row.grade or "")|e }}</td><td class="text-right">{{ row.grade_point }}</td><td>{{ _(row.registration_type)|e }}</td><td>{% if row.in_cgpa %}{{ _("Counted in CGPA") }}{% else %}{{ _("Not counted in CGPA") }}{% endif %}</td></tr>
  {% endfor %}
  </tbody>
</table>
{% endif %}
<p><strong>{{ _("CGPA") }}:</strong> {{ "%.2f"|format(r.cgpa or 0) }} &nbsp;
   <strong>{{ _("Percentage (CGPA x 10)") }}:</strong> {{ "%.2f"|format(r.percentage or 0) }} &nbsp;
   <strong>{{ _("Classification") }}:</strong> {{ (r.classification or "")|e }}{% if r.class_variant and r.class_variant != "Regular" %} ({{ _(r.class_variant)|e }}){% endif %}</p>
{{ oc_qr_block(doc) }}
